pub fn update_perp_market_config_verify_account_keys(
    accounts: UpdatePerpMarketConfigAccounts<'_, '_>,
    keys: UpdatePerpMarketConfigKeys,
) -> Result<(), (Pubkey, Pubkey)> {
    for (actual, expected) in [
        (*accounts.admin.key, keys.admin),
        (*accounts.state.key, keys.state),
        (*accounts.perp_market.key, keys.perp_market),
    ] {
        if actual != expected {
            return Err((actual, expected));
        }
    }
    Ok(())
}
pub fn update_perp_market_config_verify_writable_privileges<'me, 'info>(
    accounts: UpdatePerpMarketConfigAccounts<'me, 'info>,
) -> Result<(), (&'me AccountInfo<'info>, ProgramError)> {
    for should_be_writable in [accounts.perp_market] {
        if !should_be_writable.is_writable {
            return Err((should_be_writable, ProgramError::InvalidAccountData));
        }
    }
    Ok(())
}
pub fn update_perp_market_config_verify_signer_privileges<'me, 'info>(
    accounts: UpdatePerpMarketConfigAccounts<'me, 'info>,
) -> Result<(), (&'me AccountInfo<'info>, ProgramError)> {
    for should_be_signer in [accounts.admin] {
        if !should_be_signer.is_signer {
            return Err((should_be_signer, ProgramError::MissingRequiredSignature));
        }
    }
    Ok(())
}
pub fn update_perp_market_config_verify_account_privileges<'me, 'info>(
    accounts: UpdatePerpMarketConfigAccounts<'me, 'info>,
) -> Result<(), (&'me AccountInfo<'info>, ProgramError)> {
    update_perp_market_config_verify_writable_privileges(accounts)?;
    update_perp_market_config_verify_signer_privileges(accounts)?;
    Ok(())
}
